import assert from "node:assert/strict";
import {createElement} from "react";
import {renderToStaticMarkup} from "react-dom/server";
import type {Block} from "../../src/core/types";
import type {GeneratedBody} from "../../src/core/generators/definition";
import {Legacy2018TechnicalFigure} from "../../src/ui/Legacy2018TechnicalFigures";
import {legacy2018TechnicalTraceFacts as facts} from "./legacy-2018-technical-trace-review";
const decode=(s:string)=>s.replaceAll("&gt;",">").replaceAll("&lt;","<").replaceAll("&amp;","&");
export const technicalAttr=(s:string,key:string)=>{const m=s.match(new RegExp(`(?:^|\\s)${key}="([^"]*)"`));assert(m,`${key}: ${s}`);return decode(m[1]);};
const nums=(s:string,keys:string[])=>keys.map(k=>Number(technicalAttr(s,k)));
const para=(b:Block)=>{assert(b.type==="paragraph");return b.text;};
const options=(b:GeneratedBody)=>b.choices.map(bs=>{assert.equal(bs.length,1);return para(bs[0]);});
export function legacy2018TechnicalSvg(b:Block){assert(b.type==="diagram"&&b.scene.kind==="source_figure");assert(b.alt);return renderToStaticMarkup(createElement(Legacy2018TechnicalFigure,{profile:b.scene.profile,values:b.scene.values,caption:b.caption??""}));}
/** Reconstructs the rectangular grid and P/R/Q coordinates from actual lines
 * and circles. It never reads the scene values to derive the answer. */
export function legacy2018ReadGrid(svg:string){const lines=[...svg.matchAll(/<line\b([^>]*)/g)].map(m=>nums(m[1],["x1","y1","x2","y2"])),vertical=lines.filter(([a,,c])=>a===c),horizontal=lines.filter(([,b,,d])=>b===d);assert.equal(vertical.length+horizontal.length,lines.length);const xs=vertical.map(l=>l[0]).sort((a,b)=>a-b),ys=horizontal.map(l=>l[1]).sort((a,b)=>b-a);assert.equal(new Set(xs).size,xs.length);assert.equal(new Set(ys).size,ys.length);for(const [a,b,c,d] of vertical){assert.equal(a,c);assert.equal(b,Math.min(...ys));assert.equal(d,Math.max(...ys));}for(const [a,b,c,d] of horizontal){assert.equal(b,d);assert.equal(a,Math.min(...xs));assert.equal(c,Math.max(...xs));}assert(xs.slice(1).every((n,i)=>n-xs[i]===100));assert(ys.slice(1).every((n,i)=>ys[i]-n===60));const points:Record<string,number[]>={};for(const m of svg.matchAll(/<g data-point="([PRQ])">([\s\S]*?)<\/g>/g)){const circle=m[2].match(/<circle\b([^>]*)/);assert(circle);const [x,y,r]=nums(circle[1],["cx","cy","r"]);assert.equal(r,6);assert(xs.includes(x)&&ys.includes(y));const label=m[2].match(/<text\b([^>]*)>([^<]*)<\/text>/);assert(label);assert.equal(label[2],m[1]);const offset=facts.gridLabelOffsets[m[1] as keyof typeof facts.gridLabelOffsets];assert.deepEqual(nums(label[1],["x","y"]),[x+offset[0],y+offset[1]]);assert.equal(technicalAttr(label[1],"text-anchor"),"middle");points[m[1]]=[xs.indexOf(x),ys.indexOf(y)];}assert.deepEqual(Object.keys(points).sort(),["P","Q","R"]);assert.deepEqual(points.P,[0,0]);assert.deepEqual(points.Q,[xs.length-1,ys.length-1]);return{w:xs.length-1,h:ys.length-1,r:points.R};}
/** Enumerates every right/up shortest walk, separately tracking whether R was
 * visited; production uses a product of binomial coefficients instead. */
function gridWalks(w:number,h:number,r:number[]){let all=0,via=0;function walk(x:number,y:number,seen:boolean){seen=seen||(x===r[0]&&y===r[1]);if(x===w&&y===h){all++;if(seen)via++;return;}if(x<w)walk(x+1,y,seen);if(y<h)walk(x,y+1,seen);}walk(0,0,false);return{all,via};}
export function legacy2018ReadStack(svg:string){const root=svg.match(/<svg\b([^>]*)/);assert(root);assert.equal(technicalAttr(root[1],"viewBox"),"0 0 220 310");assert.equal(technicalAttr(root[1],"style"),"width:min(calc(220px * var(--image-scale, 1)), calc(100% * var(--image-scale, 1)))");const outline=svg.match(/<polyline\b([^>]*)/);assert(outline);assert.equal(technicalAttr(outline[1],"points"),"65,35 65,255 155,255 155,35");const lines=[...svg.matchAll(/<line\b([^>]*)/g)].map(m=>nums(m[1],["x1","y1","x2","y2"]));assert.deepEqual(lines,[[65,105,155,105],[65,155,155,155],[65,205,155,205]]);const texts=[...svg.matchAll(/<text\b([^>]*)>([^<]*)<\/text>/g)];assert.equal(texts.length,3);const cells=texts.map((m,i)=>{assert.equal(Number(technicalAttr(m[1],"x")),110);assert.equal(Number(technicalAttr(m[1],"y")),130+i*50);assert(/^[1-7]$/.test(m[2]));return Number(m[2]);});return cells;}
export function legacy2018ReadList(svg:string){const rows=svg.split('<g data-array="').slice(1);assert.equal(rows.length,2);const result:Record<string,(number|string)[]>={};for(const raw of rows){const name=raw.slice(0,raw.indexOf('"'));assert(["box","next"].includes(name));const rect=raw.match(/<rect\b([^>]*)/);assert(rect);const row=name==="box"?0:1;const heading=raw.match(/<text\b([^>]*)>([^<]*)<\/text>/);assert(heading);const fixed=facts.listRowLabels[row];assert.equal(heading[2],fixed.text);assert.deepEqual(nums(heading[1],["x","y"]),[fixed.x,fixed.y]);assert.equal(technicalAttr(heading[1],"text-anchor"),"end");assert.deepEqual(nums(rect[1],["x","y","width","height"]),[100,90+145*row,750,50]);const indices=[...raw.matchAll(/<text\b([^>]*data-index="[^"]*"[^>]*)>([^<]*)<\/text>/g)];assert.equal(indices.length,10);const cells=[...raw.matchAll(/<text\b([^>]*data-array-cell="[^"]*"[^>]*)>([^<]*)<\/text>/g)];assert.equal(cells.length,10);result[name]=cells.map((m,i)=>{assert.equal(Number(technicalAttr(indices[i][1],"data-index")),i);assert.equal(indices[i][2],String(i));assert.deepEqual(nums(indices[i][1],["x","y"]),[137.5+i*75,65+145*row]);assert.equal(Number(technicalAttr(m[1],"data-array-cell")),i);assert.deepEqual(nums(m[1],["x","y"]),[137.5+i*75,115+145*row]);return m[2]===""?"":name==="next"?Number(m[2]):m[2];});}assert.deepEqual(result.box,["","A","B","C","D","E","F","G","H","I"]);return result.next;}
export function legacy2018ReadFetch(svg:string){const boxes=[...svg.matchAll(/<rect\b([^>]*)/g)].map(m=>({name:technicalAttr(m[1],"data-box"),rect:nums(m[1],["x","y","width","height"])}));assert.deepEqual(boxes,[{name:"processor",rect:[290,45,455,165]},{name:"memory",rect:[45,105,170,75]},{name:"a",rect:[335,105,145,75]},{name:"decoder",rect:[535,105,180,75]}]);const texts=[...svg.matchAll(/<text\b([^>]*)>([^<]*)<\/text>/g)];assert.equal(texts.length,4);assert.deepEqual(texts.map(m=>({text:m[2],x:Number(technicalAttr(m[1],"x")),y:Number(technicalAttr(m[1],"y"))})),facts.fetchLabels.map(({text,x,y})=>({text,x,y})));for(const label of facts.fetchLabels){const box=boxes.find(b=>b.name===label.box)!;assert(box);const [x,y,w,h]=box.rect;assert(label.x>x&&label.x<x+w&&label.y>y&&label.y<y+h);}const lines=[...svg.matchAll(/<line\b([^>]*)/g)];assert.equal(lines.length,2);assert.deepEqual(lines.map(m=>nums(m[1],["x1","y1","x2","y2"])),[[215,142.5,335,142.5],[480,142.5,535,142.5]]);for(const m of lines){const target=technicalAttr(m[1],"marker-end").match(/^url\(#(.+)\)$/);assert(target);const marker=[...svg.matchAll(/<marker\b([^>]*)>([\s\S]*?)<\/marker>/g)].find(m=>technicalAttr(m[1],"id")===target[1]);assert(marker);assert.equal(technicalAttr(marker[1],"orient"),"auto");const path=marker[2].match(/<path\b([^>]*)/);assert(path);assert.equal(technicalAttr(path[1],"d"),"M 1 1 L 11 6 L 1 11");}return"フェッチした命令";}
export function legacy2018TechnicalTraceOracle(source:string,b:GeneratedBody,v:number[]){assert.equal(b.choices.length,4);let truth:boolean[];
 if(source.endsWith("-2")){assert.equal(v.length,1);assert(v[0]>=0&&v[0]<8&&Number.isInteger(v[0]));assert.equal(b.prompt.length,2);assert.equal(para(b.prompt[0]),"図の線上を、点Pから点Rを通って、点Qに至る最短経路は何通りあるか。");const g=legacy2018ReadGrid(legacy2018TechnicalSvg(b.prompt[1]));assert.deepEqual([g.w,g.h,...g.r],facts.grids[v[0]]);const answer=gridWalks(g.w,g.h,g.r).via;assert.equal(answer,facts.gridAnswer[v[0]]);const choices=options(b).map(Number);assert.equal(new Set(choices).size,4);const [w,h,x,y]=facts.grids[v[0]];const a=gridWalks(x,y,[x,y]).all,c=gridWalks(w-x,h-y,[w-x,h-y]).all;assert.deepEqual(choices,[a+c,x*y*(w-x)*(h-y),2**(w-x+h-y),answer]);assert(choices.slice(0,3).every(n=>Math.abs(n-answer)/answer>=7/30-1e-10));truth=choices.map(n=>n===answer);assert(b.explanation.includes(`${a}×${c}=${answer}`));}
 else if(source.endsWith("-5")){assert.equal(b.prompt.length,5);assert.deepEqual(b.prompt.slice(0,4).map(para),["次の二つのスタック操作を定義する。","PUSH n：スタックにデータ（整数値n）をプッシュする。","POP：スタックからデータをポップする。","空のスタックに対して、次の順序でスタック操作を行った結果はどれか。"]);const ops=para(b.prompt[4]).split(" → ").map(s=>s==="POP"?0:Number(s.replace(/^PUSH /,"")));assert.deepEqual(ops,facts.stackOperations[v[0]]);const top:number[]=[],fifo:number[]=[];for(const n of ops){if(n){top.unshift(n);fifo.push(n);}else{assert(top.length&&fifo.length);top.shift();fifo.shift();}}const actual=b.choices.map(bs=>{assert.equal(bs.length,1);return legacy2018ReadStack(legacy2018TechnicalSvg(bs[0]));});assert.deepEqual(actual,[[...top].reverse(),[...fifo].reverse(),top,fifo]);assert.equal(new Set(actual.map(a=>a.join(","))).size,4);truth=actual.map(a=>a.join(",")===top.join(","));assert(b.explanation.includes(`最後は底から${[...top].reverse().join("、")}`));}
 else if(source.endsWith("-6")){assert.equal(v.length,2);assert.equal(b.prompt.length,2);const stem=para(b.prompt[0]);assert.equal(stem,`リストを二つの1次元配列で実現する。配列要素box[i]とnext[i]の対がリストの一つの要素に対応し、box[i]に要素の値が入り、next[i]に次の要素の番号が入る。配列が図の状態の場合、リストの${v[1]}番目と${v[1]+1}番目との間に値がHである要素を挿入したときのnext[8]の値はどれか。ここで、next[0]がリストの先頭（1番目）の要素を指し、next[i]の値が0である要素はリストの最後を示し、next[i]の値が空白である要素はリストに連結されていない。`);const next=legacy2018ReadList(legacy2018TechnicalSvg(b.prompt[1]));const order:number[]=[];let pointer=Number(next[0]);while(pointer!==0){assert(!order.includes(pointer)&&order.length<10);order.push(pointer);assert.notEqual(next[pointer],"");pointer=Number(next[pointer]);}assert.deepEqual(order,facts.listOrders[v[0]]);for(const index of [4,6,8,9])assert.equal(next[index],"");assert.equal(next[order.at(-1)!],0);const after=order[v[1]],expected=[order[v[1]-1],v[1]===1?0:order[v[1]-2],after,8];assert.deepEqual(options(b).map(Number),expected);truth=expected.map(n=>n===after);assert(b.explanation.includes(`next[8]=${after}`));}
 else{assert(source.endsWith("-9"));assert.equal(b.prompt.length,2);assert.equal(para(b.prompt[0]),"図はプロセッサによってフェッチされた命令の格納順序を表している。aに当てはまるものはどれか。");const role=legacy2018ReadFetch(legacy2018TechnicalSvg(b.prompt[1])),expected=[...facts.fetchChoices.map((pair,i)=>pair[v[i]]),"命令レジスタ"];assert.deepEqual(options(b),expected);truth=expected.map(s=>facts.fetchRoles[s as keyof typeof facts.fetchRoles]===role);for(const part of ["命令レジスタ","次に実行する命令の位置","アドレスへの変換情報","スタック上端の位置"])assert(b.explanation.includes(part));}
 assert.equal(truth.filter(Boolean).length,1);assert.equal(b.correctIndex,truth.indexOf(true));return truth;
}
